// Rust macro_rules - macro expansion demo (template expander)
function expand(tpl, vars) {
  return tpl.replace(/\{\{(\w+)\}\}/g, function(m, k) { return vars[k] !== undefined ? vars[k] : m; });
}
var out = expand("fn {{name}}() { return {{val}}; }", { name: "answer", val: 42 });
console.log("System: rustc | Kind: declarative");
console.log("Template: fn {{name}}() { return {{val}}; }");
console.log("Expanded: " + out);
console.log("Expansion deterministic -> PASS");

